function calcXP(stamps,skills,cats){
  let t=0;
  cats.forEach(c=>(skills[c.id]||[]).forEach(sk=>{if(stamps[sk.id])t+=(c.xp||30)*sk.star;}));
  return t;
}
function getLevel(xp){let l=LEVELS[0];for(const x of LEVELS){if(xp>=x.min)l=x;}return l;}
function getNextLevel(xp){return LEVELS.find(l=>l.min>xp)||null;}
function checkBadges(stamps,sc,xp,str,tot){return BADGES.filter(b=>{try{return b.cond(stamps,sc,xp,str,tot);}catch{return false;}});}
// localStorage (Artifact永続ストレージ) ヘルパー
async function storagGet(k,fb){
  try{
    const r=await localStorage.getItem
(k);
    if(r&&r.value!=null) return JSON.parse(r.value);
    return fb;
  }catch{ return fb; }
}
async function storagSet(k,v){
  try{ await localStorage.setItem(k,JSON.stringify(v)); }catch{}
}
// 全データを一括ロード
async function loadAllData(){
  const [storedCats,skills,cfg,stamps,streak,badges,name,memories]=await Promise.all([
    storagGet("sc3_cats",DEFAULT_CATEGORIES),
    storagGet("sc3_skills",DEFAULT_SKILLS),
    storagGet("sc3_cfg",DEFAULT_CONFIG),
    storagGet("sc3_stamps",{}),
    storagGet("sc3_streak",{count:0,lastDate:""}),
    storagGet("sc3_badges",[]),
    storagGet("sc3_name",""),
    storagGet("sc3_memories",[]),
  ]);
  // ストレージのcatsとDEFAULT_CATEGORIESをマージ
  // → icon/color/labelはDEFAULTを優先し、xpなど管理者が変更した値は保持
  const cats=DEFAULT_CATEGORIES.map(def=>{
    const stored=storedCats.find(s=>s.id===def.id);
    if(!stored) return def;
    // 管理者がカスタムしたxp・labelは保持、それ以外はDEFAULTで上書き
    return {...def, xp:stored.xp??def.xp, label:stored.label??def.label};
  });
  // ストレージにないカスタムカテゴリはそのまま追加
  const customCats=storedCats.filter(s=>!DEFAULT_CATEGORIES.find(d=>d.id===s.id));
  return {cats:[...cats,...customCats],skills,cfg,stamps,streak,earnedBadges:badges,playerName:name,memories};
}

