//  共通コンポーネント
// ============================================================
function Stars({count,editable,onChange,size="1rem"}){
  return(
    <span>{[1,2,3].map(i=>(
      <span key={i} onClick={()=>editable&&onChange?.(i)}
        style={{color:i<=count?"#ffd60a":"#1e1e4a",fontSize:size,
          cursor:editable?"pointer":"default",
          textShadow:i<=count?"0 0 8px #ffd60a99":"none",transition:"all .15s"}}>★</span>
    ))}</span>
  );
}

function XPBar({xp}){
  const lv=getLevel(xp),next=getNextLevel(xp);
  const pct=next?Math.min((xp-lv.min)/(next.min-lv.min)*100,100):100;
  return(
    <div style={{display:"flex",alignItems:"center",gap:8}}>
      <div style={{background:`${lv.color}22`,border:`1px solid ${lv.color}55`,borderRadius:8,
        padding:"2px 8px",fontSize:".66rem",fontWeight:800,color:lv.color,whiteSpace:"nowrap",letterSpacing:1}}>
        Lv.{lv.lv} {lv.name}
      </div>
      <div style={{flex:1}}>
        <div style={{height:8,background:"rgba(255,255,255,.06)",borderRadius:99,overflow:"hidden"}}>
          <div style={{height:"100%",width:`${pct}%`,
            background:`linear-gradient(90deg,${lv.color}88,${lv.color})`,
            borderRadius:99,transition:"width .6s ease",boxShadow:`0 0 8px ${lv.color}55`}}/>
        </div>
        <div style={{fontSize:".56rem",color:"#3a3a7a",marginTop:2}}>
          {next?`${xp} / ${next.min} XP`:"MAX LEVEL 🏆"}
        </div>
      </div>
    </div>
  );
}

