// ============================================================
//  バッジポップアップ（新デザイン）
// ============================================================
// ============================================================
//  🔊 Web Audio サウンドエンジン（iOS Safari対応版）
// ============================================================
let _audioCtx = null;
let _audioUnlocked = false;

// AudioContextをユーザー操作時に初期化・アンロック
function unlockAudio(){
  if(_audioUnlocked) return;
  try{
    const C = window.AudioContext || window.webkitAudioContext;
    if(!C) return;
    if(!_audioCtx) _audioCtx = new C();
    // iOSのロック解除：無音バッファを再生
    const buf = _audioCtx.createBuffer(1,1,22050);
    const src = _audioCtx.createBufferSource();
    src.buffer = buf;
    src.connect(_audioCtx.destination);
    src.start(0);
    if(_audioCtx.state === 'suspended') _audioCtx.resume();
    _audioUnlocked = true;
  }catch(e){}
}

function getCtx(){
  if(!_audioCtx){
    const C = window.AudioContext || window.webkitAudioContext;
    if(!C) return null;
    _audioCtx = new C();
  }
  if(_audioCtx.state === 'suspended'){
    _audioCtx.resume();
  }
  return _audioCtx;
}

// バッジ獲得サウンド（ファンファーレ）
function playBadgeSound(){
  const ctx=getCtx(); if(!ctx) return;
  try{
    const master=ctx.createGain();
    master.gain.setValueAtTime(0.45, ctx.currentTime);
    master.connect(ctx.destination);
    const notes=[
      {freq:523.25, t:0,    dur:0.18},
      {freq:659.25, t:0.13, dur:0.18},
      {freq:783.99, t:0.25, dur:0.18},
      {freq:1046.5, t:0.36, dur:0.55},
    ];
    notes.forEach(({freq,t,dur})=>{
      const osc=ctx.createOscillator();
      const g=ctx.createGain();
      osc.type='triangle';
      osc.frequency.setValueAtTime(freq, ctx.currentTime+t);
      g.gain.setValueAtTime(0.45, ctx.currentTime+t);
      g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime+t+dur);
      osc.connect(g); g.connect(master);
      osc.start(ctx.currentTime+t);
      osc.stop(ctx.currentTime+t+dur+0.05);
      // 倍音
      const osc2=ctx.createOscillator();
      const g2=ctx.createGain();
      osc2.type='sine';
      osc2.frequency.setValueAtTime(freq*2, ctx.currentTime+t);
      g2.gain.setValueAtTime(0.12, ctx.currentTime+t);
      g2.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime+t+dur*0.6);
      osc2.connect(g2); g2.connect(master);
      osc2.start(ctx.currentTime+t);
      osc2.stop(ctx.currentTime+t+dur);
    });
    // キラキラ
    const sh=ctx.createOscillator();
    const sg=ctx.createGain();
    sh.type='sine';
    sh.frequency.setValueAtTime(2200, ctx.currentTime+0.36);
    sh.frequency.exponentialRampToValueAtTime(3400, ctx.currentTime+0.85);
    sg.gain.setValueAtTime(0.14, ctx.currentTime+0.36);
    sg.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime+0.85);
    sh.connect(sg); sg.connect(master);
    sh.start(ctx.currentTime+0.36);
    sh.stop(ctx.currentTime+0.9);
    master.gain.setValueAtTime(0.45, ctx.currentTime+0.5);
    master.gain.linearRampToValueAtTime(0, ctx.currentTime+1.05);
  }catch(e){}
}

// スタンプ完了サウンド
function playStampSound(){
  const ctx=getCtx(); if(!ctx) return;
  try{
    const master=ctx.createGain();
    master.gain.setValueAtTime(0.5, ctx.currentTime);
    master.connect(ctx.destination);
    [{freq:440,t:0,dur:0.12},{freq:554,t:0.09,dur:0.12},{freq:659,t:0.18,dur:0.28}].forEach(({freq,t,dur})=>{
      const osc=ctx.createOscillator();
      const g=ctx.createGain();
      osc.type='sine';
      osc.frequency.setValueAtTime(freq, ctx.currentTime+t);
      g.gain.setValueAtTime(0.5, ctx.currentTime+t);
      g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime+t+dur);
      osc.connect(g); g.connect(master);
      osc.start(ctx.currentTime+t);
      osc.stop(ctx.currentTime+t+dur+0.05);
    });
    master.gain.setValueAtTime(0.5, ctx.currentTime+0.3);
    master.gain.linearRampToValueAtTime(0, ctx.currentTime+0.55);
  }catch(e){}
}

// レベルアップサウンド
function playLevelUpSound(){
  const ctx=getCtx(); if(!ctx) return;
  try{
    const master=ctx.createGain();
    master.gain.setValueAtTime(0.45, ctx.currentTime);
    master.connect(ctx.destination);
    [261.6,329.6,392,523.3,659.3,783.9,1046.5].forEach((freq,i)=>{
      const t=i*0.1;
      const osc=ctx.createOscillator();
      const g=ctx.createGain();
      osc.type=i<4?'triangle':'sine';
      osc.frequency.setValueAtTime(freq, ctx.currentTime+t);
      g.gain.setValueAtTime(0.4, ctx.currentTime+t);
      g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime+t+(i===6?1.2:0.28));
      osc.connect(g); g.connect(master);
      osc.start(ctx.currentTime+t);
      osc.stop(ctx.currentTime+t+1.3);
    });
    master.gain.setValueAtTime(0.45, ctx.currentTime+0.8);
    master.gain.linearRampToValueAtTime(0, ctx.currentTime+1.5);
  }catch(e){}
}



