// ============================================================
//  スキルマップ
// ============================================================
function MapView({stamps,cats,skills,initCat,onSelect}){
  const [active,setActive]=useState(initCat||cats[0]?.id||"");
  useEffect(()=>{ if(initCat) setActive(initCat); },[initCat]);
  const cat=cats.find(c=>c.id===active);
  const list=(skills[active]||[]).map(sk=>({...sk,catId:active}));

  // スキルツリー：index 0は常に解放、それ以降は前のスキルがクリア済みなら解放
  const isUnlocked=(idx)=>{
    if(idx===0) return true;
    return !!stamps[list[idx-1]?.id];
  };

  return(
    <div>
      <div className="mcs">
        {cats.map(c=>{
          const done=(skills[c.id]||[]).filter(s=>stamps[s.id]).length;
          const tot=(skills[c.id]||[]).length;
          return(
            <button key={c.id} className={`mcb ${active===c.id?"mca":""}`}
              onClick={()=>setActive(c.id)} style={{"--c":c.color||"#00d4ff"}}>
              <span style={{fontSize:"1.4rem"}}>{c.icon}</span>
              <span style={{fontSize:".72rem",fontWeight:800}}>{c.label}</span>
              <span style={{fontSize:".58rem",color:"#4a4a8a"}}>{done}/{tot}</span>
            </button>
          );
        })}
      </div>
      {cat&&<div style={{fontSize:"1.05rem",fontWeight:900,color:cat.color,marginBottom:14,textShadow:`0 0 10px ${cat.color}`}}>
        {cat.icon} {cat.label}
      </div>}
      <div style={{display:"flex",flexDirection:"column",gap:10}}>
        {list.map((sk,i)=>{
          const unlocked=isUnlocked(i);
          const cleared=!!stamps[sk.id];
          return(
            <div key={sk.id}
              onClick={()=>unlocked&&onSelect(sk)}
              style={{
                background:cleared?"linear-gradient(135deg,#0d1e10,#071408)":unlocked?"var(--card)":"rgba(255,255,255,.02)",
                border:cleared?"1px solid #30d15844":unlocked?`1px solid var(--bdr)`:"1px dashed #1a1a3a",
                borderRadius:16,padding:14,display:"flex",alignItems:"center",gap:12,
                cursor:unlocked?"pointer":"not-allowed",
                opacity:unlocked?1:.55,
                transition:"transform .15s,border-color .2s",
                animationDelay:`${i*.07}s`,
                "--c":cat?.color||"#00d4ff",
                animation:"si .3s ease both",
              }}>
              <div style={{width:32,textAlign:"center",flexShrink:0}}>
                {cleared?(
                  <span style={{fontSize:"1.4rem"}}>✅</span>
                ):unlocked?(
                  <span style={{fontFamily:"var(--fd)",fontSize:"1.3rem",color:"#2a2a5a",lineHeight:1}}>#{i+1}</span>
                ):(
                  <span style={{fontSize:"1.4rem",filter:"grayscale(1)"}}>🔒</span>
                )}
              </div>
              <div style={{flex:1}}>
                <div style={{display:"flex",gap:8,alignItems:"center",marginBottom:4}}>
                  <Stars count={sk.star} size=".85rem"/>
                  {cleared&&<span style={{fontSize:".62rem",fontWeight:800,color:"#30d158",letterSpacing:1}}>CLEAR</span>}
                  {!unlocked&&<span style={{fontSize:".6rem",color:"#3a3a5a",fontWeight:700}}>前のスキルをクリアしよう</span>}
                </div>
                <div style={{fontWeight:900,fontSize:".98rem",marginBottom:3,
                  color:unlocked?"#fff":"#3a3a5a"}}>{sk.title}</div>
                {unlocked&&<div style={{fontSize:".7rem",color:"#4a4a8a",whiteSpace:"pre-line",lineHeight:1.5}}>{sk.desc}</div>}
              </div>
              <div style={{display:"flex",flexDirection:"column",alignItems:"flex-end",gap:4}}>
                <span style={{fontSize:".62rem",color:unlocked?`${cat?.color||"#00d4ff"}88`:"#2a2a4a",fontWeight:700}}>
                  +{(cat?.xp||30)*sk.star}xp
                </span>
                {unlocked&&<span style={{fontSize:"1.3rem",color:"#2a2a5a"}}>›</span>}
              </div>
            </div>
          );
        })}
        {list.length===0&&<div style={{textAlign:"center",color:"#2a2a5a",padding:"28px 0",fontSize:".85rem"}}>かだいがありません</div>}
      </div>
    </div>
  );
}

// ============================================================
//  動画パネル
// ============================================================
function VideoPanel({skill,catColor}){
  const url=skill.videoUrl||"";
  if(!url) return null;
  const ytId=url.match(/(?:youtu\.be\/|v=|embed\/)([A-Za-z0-9_-]{11})/)?.[1]||null;
  const thumb=ytId?`https://img.youtube.com/vi/${ytId}/mqdefault.jpg`:null;
  const open=()=>window.open(url,"_blank","noopener,noreferrer");
  return(
    <div className="vp-wrap">
      <button className="vp-btn" style={{"--c":catColor}} onClick={open}>
        {thumb?(
          <div style={{width:64,height:42,borderRadius:8,overflow:"hidden",flexShrink:0,position:"relative",border:`1px solid ${catColor}44`}}>
            <img src={thumb} alt="" style={{width:"100%",height:"100%",objectFit:"cover"}}/>
            <div style={{position:"absolute",inset:0,display:"flex",alignItems:"center",justifyContent:"center",
              background:"rgba(0,0,0,.35)"}}>
              <div style={{width:20,height:20,background:"#ff2d55",borderRadius:"50%",
                display:"flex",alignItems:"center",justifyContent:"center",fontSize:".6rem"}}>▶</div>
            </div>
          </div>
        ):(
          <span className="vp-btn-icon">▶</span>
        )}
        <div style={{flex:1,textAlign:"left"}}>
          <div className="vp-btn-text">📺 お手本どうがを みる</div>
          <div style={{fontSize:".6rem",color:"rgba(255,255,255,.4)",marginTop:2,
            overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",maxWidth:180}}>{url}</div>
        </div>
        <span className="vp-btn-yt">YouTube</span>
      </button>
    </div>
  );
}

// ============================================================
//  詳細
// ============================================================
function DetailView({skill,stamped,cats,memories,setMemories,onBack,onStamp,onUnstamp,stampMs,unstampMs,xpGain}){
  const cat=cats.find(c=>c.id===skill.catId)||cats[0];
  const catColor=cat?.color||"#00d4ff";
  const [showMemForm,setShowMemForm]=useState(false);
  const [memUrl,setMemUrl]=useState("");
  const [memNote,setMemNote]=useState("");
  const [memSaved,setMemSaved]=useState(false);
  const fileRef=useRef(null);
  const existingMem=memories.filter(m=>m.skillId===skill.id);

  const handleFilePick=(e)=>{
    const file=e.target.files?.[0];
    if(!file)return;
    const reader=new FileReader();
    reader.onload=ev=>{ setMemUrl(ev.target.result); };
    reader.readAsDataURL(file);
  };

  const saveMem=()=>{
    if(!memUrl&&!memNote.trim())return;
    const newMem={
      id:`mem_${Date.now()}`,
      skillId:skill.id,
      skillTitle:skill.title,
      catId:skill.catId,
      catIcon:cat?.icon||"⚽",
      catColor,
      mediaUrl:memUrl,
      mediaType:memUrl.startsWith("data:video")?"video":memUrl.startsWith("data:")?"image":"url",
      note:memNote.trim(),
      date:new Date().toLocaleDateString("ja-JP"),
    };
    setMemories(p=>[newMem,...p]);
    setMemSaved(true);
    setMemUrl(""); setMemNote("");
    setTimeout(()=>{setShowMemForm(false);setMemSaved(false);},1500);
  };

  return(
    <div>
      <button className="bkb" onClick={onBack}>‹ もどる</button>
      <div className="dh" style={{"--c":catColor}}>
        <div className="dh-glow"/>
        <span style={{fontSize:"3.8rem",display:"block",marginBottom:8,filter:`drop-shadow(0 0 20px ${catColor})`}}>
          {cat?.icon}
        </span>
        <Stars count={skill.star} size="1.3rem"/>
        <div style={{fontSize:"1.3rem",fontWeight:900,marginTop:8}}>{skill.title}</div>
        <div style={{fontSize:".73rem",color:`${catColor}cc`,marginTop:6,fontWeight:700,letterSpacing:1}}>
          クリアで ＋{xpGain} XP ⚡
        </div>
      </div>
      <div className="dd">{skill.detail}</div>
      <VideoPanel skill={skill} catColor={catColor}/>
      <div className="sz">
        <div style={{fontSize:".8rem",fontWeight:800,color:stamped?"#30d158":"#3a3a7a",marginBottom:18,letterSpacing:1}}>
          {stamped?"🎉 クリア！すごいぞ！":"🔒 クリアしたらスタンプをもらおう！"}
        </div>
        <div style={{display:"flex",justifyContent:"center"}}>
          <StampButton stamped={stamped} onStamp={onStamp} onUnstamp={onUnstamp}
            stampMs={stampMs} unstampMs={unstampMs} catColor={catColor}/>
        </div>
      </div>
      {stamped&&(
        <div className="mem-zone" style={{"--c":catColor}}>
          <div className="mem-zone-title">
            <span>🎬 チャレンジのおもいでを のこそう！</span>
            {existingMem.length>0&&(
              <span style={{fontSize:".62rem",color:catColor,fontWeight:700}}>
                {existingMem.length}件 保存ずみ
              </span>
            )}
          </div>
          {!showMemForm?(
            <button className="mem-open-btn" style={{"--c":catColor}}
              onClick={()=>setShowMemForm(true)}>
              <span style={{fontSize:"1.4rem"}}>📸</span>
              <span style={{fontWeight:800,fontSize:".88rem"}}>どうが・しゃしんを のこす</span>
              <span style={{fontSize:".7rem",opacity:.6}}>＋</span>
            </button>
          ):(
            <div className="mem-form">
              {memSaved?(
                <div style={{textAlign:"center",padding:"20px 0",color:"#30d158",fontWeight:800,fontSize:"1rem"}}>
                  ✅ ほぞんしました！
                </div>
              ):(
                <>
                  <input ref={fileRef} type="file" accept="image/*,video/*" style={{display:"none"}}
                    onChange={handleFilePick}/>
                  <div style={{display:"flex",gap:8,marginBottom:10}}>
                    <button className="mem-file-btn" style={{"--c":catColor}}
                      onClick={()=>fileRef.current?.click()}>
                      📁 ファイルをえらぶ
                    </button>
                    <div style={{flex:1,fontSize:".65rem",color:"#3a3a7a",display:"flex",alignItems:"center",
                      overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>
                      {memUrl?(memUrl.startsWith("data:")?"ファイルせんたく済み ✅":memUrl):"しゃしん・どうがをえらんでね"}
                    </div>
                  </div>
                  {memUrl&&memUrl.startsWith("data:image")&&(
                    <img src={memUrl} alt="preview" style={{width:"100%",borderRadius:10,marginBottom:10,maxHeight:180,objectFit:"cover"}}/>
                  )}
                  {memUrl&&memUrl.startsWith("data:video")&&(
                    <video src={memUrl} controls style={{width:"100%",borderRadius:10,marginBottom:10,maxHeight:180}}/>
                  )}
                  <textarea className="ai" value={memNote} onChange={e=>setMemNote(e.target.value)}
                    placeholder="ひとことメモ（れい：はじめてできた！）"
                    style={{minHeight:56,resize:"vertical",marginBottom:10,fontSize:".84rem"}}/>
                  <div style={{display:"flex",gap:8}}>
                    <button className="ab" style={{flex:1,
                      background:`linear-gradient(135deg,${catColor}88,${catColor})`,
                      opacity:(!memUrl&&!memNote.trim())?0.4:1}}
                      onClick={saveMem}>
                      💾 ほぞんする
                    </button>
                    <button className="ab" style={{background:"rgba(255,255,255,.06)",border:"1px solid #2a2a5a"}}
                      onClick={()=>{setShowMemForm(false);setMemUrl("");setMemNote("");}}>
                      とじる
                    </button>
                  </div>
                </>
              )}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

// ============================================================
//  おもいでページ
// ============================================================
function MemoriesView({memories,setMemories,cats,skills,playerName}){
  const [delId,setDelId]=useState(null);
  const del=(id)=>{setMemories(p=>p.filter(m=>m.id!==id));setDelId(null);};
  return(
    <div>
      <div className="book-hdr" style={{background:"linear-gradient(135deg,#0a0a28,#140a30)",borderColor:"#bf5af244"}}>
        <div style={{fontSize:"2.2rem",marginBottom:4}}>🎬</div>
        <div style={{fontFamily:"var(--fd)",fontSize:"1.4rem",letterSpacing:3,
          background:"linear-gradient(90deg,#bf5af2,#ff2d55)",
          WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent"}}>
          おもいで
        </div>
        <div style={{fontSize:".76rem",color:"#4a4a8a",marginTop:4}}>
          {playerName}の チャレンジ記録 · {memories.length}件
        </div>
      </div>
      {memories.length===0?(
        <div style={{textAlign:"center",padding:"40px 20px",color:"#2a2a5a"}}>
          <div style={{fontSize:"3rem",marginBottom:12}}>📷</div>
          <div style={{fontSize:".88rem",fontWeight:800,marginBottom:6}}>まだおもいでがありません</div>
          <div style={{fontSize:".74rem",lineHeight:1.7}}>
            スキルをクリアしたら<br/>どうがやしゃしんをのこしてみよう！
          </div>
        </div>
      ):(
        <div style={{display:"flex",flexDirection:"column",gap:12}}>
          {memories.map(m=>(
            <div key={m.id} className="mem-card" style={{"--c":m.catColor||"#00d4ff"}}>
              <div className="mem-card-glow"/>
              <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:10}}>
                <span style={{fontSize:"1.4rem",filter:`drop-shadow(0 0 6px ${m.catColor})`}}>{m.catIcon}</span>
                <div style={{flex:1}}>
                  <div style={{fontWeight:900,fontSize:".9rem"}}>{m.skillTitle}</div>
                  <div style={{fontSize:".62rem",color:"#3a3a7a",marginTop:2}}>{m.date}</div>
                </div>
                {delId===m.id?(
                  <div style={{display:"flex",gap:6}}>
                    <button style={{background:"#c0002a",border:"none",borderRadius:8,color:"#fff",
                      padding:"4px 10px",cursor:"pointer",fontFamily:"var(--f)",fontSize:".7rem",fontWeight:800}}
                      onClick={()=>del(m.id)}>削除</button>
                    <button style={{background:"rgba(255,255,255,.08)",border:"1px solid #2a2a5a",borderRadius:8,
                      color:"#aaa",padding:"4px 10px",cursor:"pointer",fontFamily:"var(--f)",fontSize:".7rem"}}
                      onClick={()=>setDelId(null)}>やめる</button>
                  </div>
                ):(
                  <button style={{background:"none",border:"none",color:"#2a2a5a",cursor:"pointer",
                    fontSize:"1.1rem",padding:4}} onClick={()=>setDelId(m.id)}>🗑️</button>
                )}
              </div>
              {m.mediaUrl&&m.mediaType==="image"&&(
                <img src={m.mediaUrl} alt={m.skillTitle}
                  style={{width:"100%",borderRadius:10,marginBottom:8,maxHeight:220,objectFit:"cover",
                    border:`1px solid ${m.catColor}33`}}/>
              )}
              {m.mediaUrl&&m.mediaType==="video"&&(
                <video src={m.mediaUrl} controls
                  style={{width:"100%",borderRadius:10,marginBottom:8,maxHeight:220,
                    border:`1px solid ${m.catColor}33`}}/>
              )}
              {m.note&&(
                <div style={{background:"rgba(255,255,255,.03)",border:`1px solid ${m.catColor}22`,
                  borderRadius:10,padding:"8px 12px",fontSize:".8rem",color:"#aaa",lineHeight:1.6}}>
                  💬 {m.note}
                </div>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ============================================================
//  バッジページ（ロゴ/国旗 切替）
// ============================================================
function BadgesView({earnedBadges,stampCount,xp,streak,total,badgeMode,setBadgeMode}){
  const got=earnedBadges.length;
  const [selected,setSelected]=useState(null); // 拡大表示中のバッジ

  const handleClick=(b,unlocked)=>{
    if(!unlocked)return; // 未取得はタップ無効
    setSelected(b);
  };

  return(
    <div>
      {selected&&(
        <div
          onClick={()=>setSelected(null)}
          style={{
            position:"fixed",inset:0,zIndex:900,
            background:"rgba(0,0,0,.75)",
            backdropFilter:"blur(8px)",
            display:"flex",alignItems:"center",justifyContent:"center",
            padding:24,
            animation:"bdgOverlayIn .2s ease",
          }}>
          <style>{`
            @keyframes bdgOverlayIn{from{opacity:0}to{opacity:1}}
            @keyframes bdgModalIn{from{opacity:0;transform:scale(.6)}to{opacity:1;transform:scale(1)}}
            @keyframes bdgShine{0%,100%{opacity:.4;transform:scale(1)}50%{opacity:.9;transform:scale(1.08)}}
          `}</style>
          <div
            onClick={e=>e.stopPropagation()}
            style={{
              background:`linear-gradient(145deg,#0e0a28,#1a1040,#0e0a28)`,
              border:`2px solid ${selected.logo.glow}88`,
              borderRadius:28,
              padding:"32px 28px",
              textAlign:"center",
              width:"min(320px,88vw)",
              boxShadow:`0 0 80px ${selected.logo.glow}55,0 0 140px ${selected.logo.glow}22,0 20px 60px rgba(0,0,0,.7)`,
              animation:"bdgModalIn .35s cubic-bezier(.34,1.4,.64,1)",
              position:"relative",overflow:"hidden",
            }}>
            <div style={{
              position:"absolute",inset:0,
              background:`radial-gradient(circle at 50% 30%,${selected.logo.glow}18,transparent 65%)`,
              pointerEvents:"none",
            }}/>
            <button
              onClick={()=>setSelected(null)}
              style={{
                position:"absolute",top:12,right:14,
                background:"rgba(255,255,255,.08)",border:"none",
                borderRadius:"50%",width:28,height:28,
                color:"#aaa",fontSize:"1rem",cursor:"pointer",
                display:"flex",alignItems:"center",justifyContent:"center",
                fontFamily:"var(--f)",
              }}>✕</button>
            <div style={{
              display:"inline-block",
              background:`linear-gradient(135deg,${selected.logo.grad[0]},${selected.logo.grad[selected.logo.grad.length-1]})`,
              borderRadius:99,padding:"3px 14px",
              fontSize:".62rem",fontWeight:900,color:"#fff",
              letterSpacing:2,marginBottom:16,
              boxShadow:`0 0 16px ${selected.logo.glow}66`,
            }}>🏅 GET!</div>
            <div style={{
              display:"flex",justifyContent:"center",alignItems:"center",marginBottom:18,
              animation:"bdgShine 2.5s ease-in-out infinite",
            }}>
              <BadgeLogo badge={selected} size={180} unlocked mode={badgeMode}/>
            </div>
            <div style={{
              fontFamily:"var(--fd)",fontSize:"1.3rem",letterSpacing:2,marginBottom:8,
              background:`linear-gradient(90deg,${selected.logo.grad[0]},${selected.logo.grad[selected.logo.grad.length-1]})`,
              WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",
            }}>{selected.name}</div>
            <div style={{
              fontSize:".8rem",color:"#8888bb",lineHeight:1.7,marginBottom:20,
            }}>{selected.desc}</div>
            <div style={{
              display:"flex",alignItems:"center",justifyContent:"center",gap:8,
              background:"rgba(255,255,255,.04)",borderRadius:12,padding:"8px 16px",
              border:`1px solid ${selected.logo.glow}22`,
            }}>
              <span style={{fontSize:"1.6rem"}}>{selected.flag.emoji}</span>
              <div style={{textAlign:"left"}}>
                <div style={{fontSize:".58rem",color:"#3a3a7a",letterSpacing:1}}>対応国</div>
                <div style={{fontSize:".8rem",fontWeight:900,color:"#fff",fontFamily:"var(--fd)",letterSpacing:1}}>{selected.flag.country}</div>
              </div>
            </div>
            <div style={{fontSize:".6rem",color:"#2a2a5a",marginTop:16}}>
              タップして閉じる
            </div>
          </div>
        </div>
      )}

      <div className="book-hdr">
        <div style={{fontSize:"2rem",marginBottom:4}}>🎖️</div>
        <div style={{fontFamily:"var(--fd)",fontSize:"1.4rem",letterSpacing:3,color:"#bf5af2",textShadow:"0 0 16px #bf5af277"}}>BADGES</div>
        <div style={{fontSize:".78rem",color:"#4a4a8a",marginTop:4}}>{got} / {BADGES.length} かくとく</div>
        <div className="bpb"><div className="bpbf" style={{width:`${Math.round(got/BADGES.length*100)}%`}}/></div>
        <div style={{display:"flex",gap:6,justifyContent:"center",marginTop:12}}>
          {[{id:"logo",label:"🏆 ロゴ"},{id:"flag",label:"🌍 国旗"}].map(m=>(
            <button key={m.id}
              onClick={()=>setBadgeMode(m.id)}
              style={{
                background:badgeMode===m.id?"linear-gradient(135deg,#003087,#0050c8)":"rgba(255,255,255,.05)",
                border:badgeMode===m.id?"1px solid #0080ff88":"1px solid #1a1a4a",
                borderRadius:99,padding:"5px 18px",
                color:badgeMode===m.id?"#fff":"#3a3a7a",
                fontFamily:"var(--f)",fontSize:".74rem",fontWeight:800,
                cursor:"pointer",transition:"all .2s",
                boxShadow:badgeMode===m.id?"0 0 14px rgba(0,80,200,.4)":"none",
              }}>{m.label}</button>
          ))}
        </div>
        {got>0&&<div style={{fontSize:".6rem",color:"#2a2a5a",marginTop:8}}>✨ 取得済みバッジをタップで拡大</div>}
      </div>

      <div style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:10,marginBottom:20}}>
        {BADGES.map(b=>{
          const g=earnedBadges.includes(b.id);
          return(
            <div key={b.id}
              className={`bi ${g?"bi-got":""}`}
              onClick={()=>handleClick(b,g)}
              style={{
                ...(g?{borderColor:`${b.logo.glow}44`,boxShadow:`0 0 18px ${b.logo.glow}22`}:{}),
                cursor:g?"pointer":"default",
                transition:"transform .15s,box-shadow .2s",
              }}>
              <div className="bi-glow"/>
              <div style={{display:"flex",justifyContent:"center",marginBottom:6}}>
                <BadgeLogo badge={b} size={54} unlocked={g} mode={badgeMode}/>
              </div>
              <div style={{fontSize:".63rem",fontWeight:800,
                color:g?b.logo.glow:"#2a2a5a",lineHeight:1.3}}>{b.name}</div>
              <div style={{fontSize:".52rem",color:g?"#8a6aa8":"#1a1a3a",marginTop:4,lineHeight:1.4}}>{b.desc}</div>
              {g&&<div style={{fontSize:".52rem",fontWeight:800,marginTop:4,letterSpacing:1,
                background:`linear-gradient(90deg,${b.logo.grad[0]},${b.logo.grad[b.logo.grad.length-1]})`,
                WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent"}}>GET! 👆</div>}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ============================================================
//  ⚔️ ボスバトルビュー
// ============================================================
function BossView({bossCleared,setBossCleared,xp,onBack,showToast,stamps,setStamps,skills,cats,earnedBadges,setEarnedBadges,streak,total}){
  const boss=getCurrentBoss();
  const cleared=bossCleared.includes(boss.id);
  const [pressing,setPressing]=useState(false);
  const [progress,setProgress]=useState(0);
  const [explode,setExplode]=useState(false);
  const ref=useRef(null);
  const lv=getLevel(xp);

  const start=useCallback((e)=>{
    if(cleared)return;
    e.preventDefault();
    setPressing(true);setProgress(0);
    const t0=Date.now();
    ref.current=setInterval(()=>{
      const el=Date.now()-t0;
      setProgress(Math.min(el/3000,1));
      if(el>=3000){
        clearInterval(ref.current);
        setExplode(true);
        playStampSound();
        setTimeout(()=>setExplode(false),1000);
        setBossCleared(p=>[...p,boss.id]);
        showToast(`🏆 ボス撃破！ ＋${boss.xp} XP！`);
        setPressing(false);setProgress(0);
      }
    },20);
  },[cleared,boss]);
  const end=useCallback(()=>{clearInterval(ref.current);setPressing(false);setProgress(0);},[]);

  const chargeColor=progress>0.66?"#ff2d55":progress>0.33?"#ffd60a":"#ff6b35";

  // 残り日数計算
  const now=Date.now();
  const weekMs=7*24*60*60*1000;
  const weekStart=Math.floor(now/weekMs)*weekMs;
  const daysLeft=Math.ceil((weekStart+weekMs-now)/(24*60*60*1000));

  return(
    <div>
      <button className="bkb" onClick={onBack}>‹ もどる</button>
      <div style={{
        background:"linear-gradient(135deg,#1a0010,#3a0020,#1a0010)",
        border:"1px solid #ff2d5544",borderRadius:22,padding:"20px 18px",
        marginBottom:16,textAlign:"center",position:"relative",overflow:"hidden",
      }}>
        <div style={{position:"absolute",inset:0,
          background:"radial-gradient(circle at 50% 30%,rgba(255,45,85,.15),transparent 65%)",
          pointerEvents:"none"}}/>
        <div style={{fontSize:".62rem",fontWeight:800,color:"#ff2d55",letterSpacing:3,marginBottom:8}}>
          ⚔️ 今週のボスバトル
        </div>
        <div style={{fontSize:"3rem",marginBottom:8,
          filter:"drop-shadow(0 0 20px #ff2d55) drop-shadow(0 0 8px #ff6b35)"}}>{boss.icon}</div>
        <div style={{fontFamily:"var(--fd)",fontSize:"1.2rem",letterSpacing:2,color:"#fff",marginBottom:6}}>
          {boss.title}
        </div>
        <div style={{fontSize:".76rem",color:"#ff6b35aa",lineHeight:1.7}}>{boss.desc}</div>
        <div style={{display:"flex",justifyContent:"center",gap:16,marginTop:12}}>
          <div style={{background:"rgba(255,45,85,.12)",border:"1px solid #ff2d5533",
            borderRadius:99,padding:"4px 14px",fontSize:".68rem",color:"#ff8899"}}>
            ⏰ あと{daysLeft}日
          </div>
          <div style={{background:"rgba(255,214,10,.12)",border:"1px solid #ffd60a33",
            borderRadius:99,padding:"4px 14px",fontSize:".68rem",color:"#ffd60a",fontWeight:800}}>
            ＋{boss.xp} XP
          </div>
        </div>
      </div>
      {cleared?(
        <div style={{
          background:"linear-gradient(135deg,#0a1e0a,#0d280d)",
          border:"2px solid #30d15866",borderRadius:22,padding:"32px",
          textAlign:"center",
        }}>
          <div style={{fontSize:"4rem",marginBottom:12,
            filter:"drop-shadow(0 0 20px #30d158)"}}>🏆</div>
          <div style={{fontFamily:"var(--fd)",fontSize:"1.4rem",letterSpacing:3,
            background:"linear-gradient(90deg,#30d158,#00d4ff)",
            WebkitBackgroundClip:"text",WebkitTextFillColor:"transparent",
            marginBottom:8}}>BOSS CLEARED!</div>
          <div style={{fontSize:".78rem",color:"#30d158aa"}}>
            {boss.reward} スペシャルバッジ獲得！来週の新ボスをお楽しみに！
          </div>
        </div>
      ):(
        <div style={{
          background:"rgba(255,255,255,.02)",border:"1px dashed #2a2a5a",
          borderRadius:20,padding:24,textAlign:"center",
        }}>
          <div style={{fontSize:".78rem",color:"#4a4a8a",marginBottom:24,lineHeight:1.8}}>
            クリアしたら下のボタンを<br/>
            <b style={{color:"#ff6b35"}}>3びょうおしつづけよう！</b>
          </div>
          <div style={{position:"relative",display:"inline-flex",alignItems:"center",justifyContent:"center"}}>
            {explode&&[...Array(12)].map((_,i)=>{
              const angle=(i/12)*360;
              return(
                <div key={i} style={{
                  position:"absolute",top:"50%",left:"50%",
                  width:10,height:10,borderRadius:"50%",
                  background:i%2===0?"#ffd60a":"#ff2d55",
                  "--dx":`${80*Math.cos(angle*Math.PI/180)}px`,
                  "--dy":`${80*Math.sin(angle*Math.PI/180)}px`,
                  animation:"chargeStarB .8s ease-out forwards",
                  pointerEvents:"none",
                }}/>
              );
            })}
            <button
              onPointerDown={start} onPointerUp={end} onPointerLeave={end}
              style={{
                width:170,height:170,borderRadius:"50%",border:"none",cursor:"pointer",
                position:"relative",overflow:"hidden",outline:"none",
                userSelect:"none",touchAction:"none",
                display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",
                background:"radial-gradient(circle at 35% 25%,#2a0010,#06000e)",
                boxShadow:pressing
                  ?`0 0 0 3px ${chargeColor},0 0 40px ${chargeColor}88`
                  :"0 0 0 2px #ff2d5544,0 8px 40px rgba(0,0,0,.8)",
                transform:pressing?"scale(.92)":"scale(1)",
                transition:"transform .1s,box-shadow .2s",
              }}>
              {pressing&&(
                <div style={{
                  position:"absolute",bottom:0,left:0,right:0,
                  height:`${progress*100}%`,
                  background:`linear-gradient(0deg,${chargeColor}ee,${chargeColor}44,transparent)`,
                  transition:"height .04s",pointerEvents:"none",
                }}/>
              )}
              <div style={{position:"relative",zIndex:2,textAlign:"center"}}>
                {pressing?(
                  <>
                    <div style={{fontSize:".7rem",fontWeight:900,color:chargeColor,letterSpacing:2,marginBottom:6}}>CHARGING</div>
                    <div style={{fontSize:"1.8rem",fontFamily:"var(--fd)",color:"#fff"}}>{Math.round(progress*100)}%</div>
                    <div style={{marginTop:8,width:90,height:5,background:"rgba(255,255,255,.1)",borderRadius:99,overflow:"hidden"}}>
                      <div style={{height:"100%",width:`${progress*100}%`,background:chargeColor,borderRadius:99,transition:"width .04s"}}/>
                    </div>
                  </>
                ):(
                  <>
                    <div style={{fontSize:"2.8rem",filter:"drop-shadow(0 0 10px #ff2d5588)"}}>⚔️</div>
                    <div style={{fontSize:".62rem",fontWeight:800,letterSpacing:2,marginTop:8,color:"#ff6b35"}}>HOLD TO</div>
                    <div style={{fontSize:".62rem",fontWeight:800,letterSpacing:2,color:"#ff6b35"}}>CLEAR!</div>
                  </>
                )}
              </div>
            </button>
          </div>
        </div>
      )}
      <div style={{marginTop:20}}>
        <div style={{fontSize:".7rem",fontWeight:800,color:"#ffd60a",letterSpacing:2,marginBottom:10}}>
          ⚔️ ボス履歴
        </div>
        <div style={{display:"flex",flexDirection:"column",gap:8}}>
          {BOSS_CHALLENGES.map(b=>{
            const done=bossCleared.includes(b.id);
            const isCurrent=b.id===boss.id;
            return(
              <div key={b.id} style={{
                display:"flex",alignItems:"center",gap:12,
                background:done?"rgba(48,209,88,.06)":isCurrent?"rgba(255,45,85,.06)":"rgba(255,255,255,.02)",
                border:`1px solid ${done?"#30d15833":isCurrent?"#ff2d5533":"#1a1a3a"}`,
                borderRadius:14,padding:"10px 14px",
              }}>
                <span style={{fontSize:"1.6rem",filter:done?`drop-shadow(0 0 8px #30d158)`:"grayscale(1) opacity(.4)"}}>{b.icon}</span>
                <div style={{flex:1}}>
                  <div style={{fontSize:".8rem",fontWeight:800,color:done?"#30d158":isCurrent?"#ff6b35":"#3a3a5a"}}>{b.title}</div>
                  <div style={{fontSize:".6rem",color:"#2a2a5a",marginTop:2}}>＋{b.xp} XP</div>
                </div>
                <div style={{fontSize:"1.2rem"}}>{done?"✅":isCurrent?"⚔️":"🔒"}</div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

function AdminLogin({pin,onOk,onBack}){
  const [v,setV]=useState(""); const [err,setErr]=useState(false);
  const sub=()=>{if(v===pin)onOk();else{setErr(true);setV("");setTimeout(()=>setErr(false),500);}};
  return(
    <div style={{display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",minHeight:"65vh",gap:18}}>
      <div style={{fontSize:"3rem"}}>🔐</div>
      <div style={{fontFamily:"var(--fd)",fontSize:"1.2rem",letterSpacing:3,color:"#ffd60a"}}>ADMIN LOGIN</div>
      <input type="password" inputMode="numeric" maxLength={6} value={v}
        onChange={e=>setV(e.target.value)} onKeyDown={e=>e.key==="Enter"&&sub()}
        placeholder="••••"
        style={{background:"#07071a",border:`2px solid ${err?"#ff2d55":"#1a1a4a"}`,borderRadius:14,
          padding:"12px 24px",color:"#fff",fontSize:"1.6rem",textAlign:"center",
          fontFamily:"monospace",width:160,letterSpacing:10,outline:"none",
          animation:err?"shake .45s ease":undefined}}/>
      {err&&<div style={{color:"#ff2d55",fontSize:".8rem",fontWeight:700}}>ちがいます！</div>}
      <div style={{display:"flex",gap:10}}>
        <button className="ab" onClick={sub}>ログイン</button>
        <button className="ab" style={{background:"rgba(255,255,255,.06)",border:"1px solid #2a2a5a"}} onClick={onBack}>もどる</button>
      </div>
      <style>{`@keyframes shake{0%,100%{transform:translateX(0)}20%,60%{transform:translateX(-8px)}40%,80%{transform:translateX(8px)}}`}</style>
    </div>
  );
}

// ============================================================
//  💾 バックアップ・リストア コンポーネント
// ============================================================
function BackupView({cats,skills,cfg,stamps,streak,earnedBadges,playerName,memories,setCats,setSkills,setCfg,setStamps,setStreak,setEarnedBadges,setPlayerName,setMemories,showToast}){
  const [restoreText,setRestoreText]=useState("");
  const [restoreErr,setRestoreErr]=useState("");
  const [restoreOk,setRestoreOk]=useState(false);
  const [copied,setCopied]=useState(false);
  const [showCopyData,setShowCopyData]=useState(false);
  const [copyData,setCopyData]=useState("");
  const fileRef=useRef(null);
  const textareaRef=useRef(null);

  // ===== JSONデータ生成 =====
  const makeJson=(full)=>{
    const data=full
      ?{version:1,exportedAt:new Date().toISOString(),playerName,cfg,cats,skills,stamps,streak,earnedBadges,memories}
      :{version:1,exportedAt:new Date().toISOString(),playerName,cfg,cats,skills,stamps,streak,earnedBadges,
        memoriesMeta:memories.map(m=>({...m,mediaUrl:m.mediaUrl?"[画像/動画データ省略]":""}))};
    return JSON.stringify(data);
  };

  // ===== クリップボードにコピー =====
  const doCopy=async(full=false)=>{
    const json=makeJson(full);
    try{
      await navigator.clipboard.writeText(json);
      setCopied(true);
      showToast("✅ クリップボードにコピーしました！");
      setTimeout(()=>setCopied(false),3000);
    }catch{
      // フォールバック：テキストエリアに表示してユーザーが手動コピー
      setCopyData(json);
      setShowCopyData(true);
      setTimeout(()=>{textareaRef.current?.select();textareaRef.current?.focus();},100);
    }
  };

  // ===== ダウンロード（PC向け） =====
  const doDownload=(full=false)=>{
    const json=makeJson(full);
    const dateStr=new Date().toLocaleDateString("ja-JP").replace(/\//g,"-");
    const fname=full?`soccer-hero-full-${dateStr}.json`:`soccer-hero-backup-${dateStr}.json`;
    const blob=new Blob([json],{type:"application/json"});
    const url=URL.createObjectURL(blob);
    const a=document.createElement("a");
    a.href=url;a.download=fname;a.click();
    URL.revokeObjectURL(url);
    showToast("✅ ダウンロードしました！");
  };

  // ===== インポート（ファイル） =====
  const handleFile=(e)=>{
    const file=e.target.files?.[0]; if(!file)return;
    const reader=new FileReader();
    reader.onload=ev=>{setRestoreText(ev.target.result);setRestoreErr("");setShowCopyData(false);};
    reader.readAsText(file);
    e.target.value="";
  };

  // ===== テキストから復元 =====
  const handlePaste=(e)=>{
    const text=e.target.value;
    setRestoreText(text);
    setRestoreErr("");
  };

  // ===== リストア =====
  const [confirmRestore,setConfirmRestore]=useState(false);

  const doRestore=()=>{
    setRestoreErr("");setRestoreOk(false);
    let data;
    try{data=JSON.parse(restoreText);}
    catch{setRestoreErr("❌ JSONの形式が正しくありません");return;}
    if(!data.version||!data.cats||!data.skills){
      setRestoreErr("❌ このファイルはSoccer Heroのバックアップではありません");return;
    }
    // window.confirmの代わりにインライン確認
    setConfirmRestore(true);
  };

  const doRestoreConfirmed=()=>{
    setConfirmRestore(false);
    let data;
    try{data=JSON.parse(restoreText);}
    catch{setRestoreErr("❌ JSONの形式が正しくありません");return;}
    try{
      if(data.cats)         {setCats(data.cats);         storagSet("sc3_cats",data.cats);}
      if(data.skills)       {setSkills(data.skills);     storagSet("sc3_skills",data.skills);}
      if(data.cfg)          {setCfg(data.cfg);           storagSet("sc3_cfg",data.cfg);}
      if(data.stamps)       {setStamps(data.stamps);     storagSet("sc3_stamps",data.stamps);}
      if(data.streak)       {setStreak(data.streak);     storagSet("sc3_streak",data.streak);}
      if(data.earnedBadges) {setEarnedBadges(data.earnedBadges);storagSet("sc3_badges",data.earnedBadges);}
      if(data.playerName)   {setPlayerName(data.playerName);storagSet("sc3_name",data.playerName);}
      if(data.memories)     {setMemories(data.memories);storagSet("sc3_memories",data.memories);}
      setRestoreText("");setRestoreOk(true);
      showToast("✅ データを復元しました！");
      setTimeout(()=>setRestoreOk(false),3000);
    }catch(err){setRestoreErr("❌ 復元に失敗しました: "+err.message);}
  };

  const stampCount=Object.values(stamps).filter(Boolean).length;
  const totalSkills=cats.reduce((a,c)=>a+(skills[c.id]?.length||0),0);

  return(
    <div>
      {/* データ概要 */}
      <div className="bk-summary">
        <div className="bk-summary-title">📊 現在のデータ</div>
        <div className="bk-summary-grid">
          {[
            {icon:"👤",label:"プレイヤー",val:playerName||"未設定"},
            {icon:"🏅",label:"スタンプ",val:`${stampCount} / ${totalSkills}`},
            {icon:"🎖️",label:"バッジ",val:`${earnedBadges.length}個`},
            {icon:"🎬",label:"おもいで",val:`${memories.length}件`},
          ].map((item,i)=>(
            <div key={i} className="bk-stat">
              <span style={{fontSize:"1.4rem"}}>{item.icon}</span>
              <div>
                <div style={{fontSize:".6rem",color:"#3a3a7a"}}>{item.label}</div>
                <div style={{fontSize:".84rem",fontWeight:800,color:"#d8d8f8"}}>{item.val}</div>
              </div>
            </div>
          ))}
        </div>
      </div>

      {/* ===== エクスポート ===== */}
      <div className="as">
        <div className="ast">💾 バックアップ（エクスポート）</div>

        {/* 方法①：コピー → メモに貼り付け */}
        <div style={{
          background:"linear-gradient(135deg,rgba(48,209,88,.1),rgba(0,180,60,.06))",
          border:"1px solid rgba(48,209,88,.3)",borderRadius:14,
          padding:"12px 14px",marginBottom:12,
        }}>
          <div style={{fontSize:".72rem",fontWeight:800,color:"#30d158",marginBottom:6}}>
            📋 方法① コピー → メモに貼り付け（iPhone推奨）
          </div>
          <div style={{fontSize:".68rem",color:"#2a6a3a",lineHeight:1.8,marginBottom:10}}>
            データをコピーして<b style={{color:"#60d880"}}>「メモ」アプリや「メール」に貼り付けて</b>保存。
            復元時は貼り付けたテキストをまたコピーして使います。
          </div>
          <div style={{display:"flex",gap:8}}>
            <button className="bk-export-btn" style={{flex:1,margin:0}}
              onClick={()=>doCopy(false)}>
              <div className="bk-export-icon" style={{background:"linear-gradient(135deg,#30d158,#00a040)",width:32,height:32,fontSize:"1rem"}}>
                {copied?"✅":"📋"}
              </div>
              <div style={{flex:1}}>
                <div style={{fontWeight:800,fontSize:".82rem"}}>
                  {copied?"コピーしました！":"進捗データをコピー"}
                </div>
                <div style={{fontSize:".6rem",color:"rgba(255,255,255,.4)"}}>スタンプ・バッジ・設定</div>
              </div>
            </button>
          </div>
        </div>

        {/* コピーデータ表示エリア（クリップボード失敗時） */}
        {showCopyData&&(
          <div style={{marginBottom:12}}>
            <div style={{fontSize:".68rem",color:"#ffd60a",marginBottom:6,fontWeight:700}}>
              ⚠️ 下のテキストを全選択→コピーして「メモ」アプリに貼り付けてください
            </div>
            <textarea
              ref={textareaRef}
              readOnly
              value={copyData}
              style={{
                width:"100%",height:100,background:"#06061a",
                border:"2px solid #ffd60a88",borderRadius:10,
                padding:"8px",color:"#d8d8f8",fontSize:".6rem",
                fontFamily:"monospace",resize:"none",
                boxSizing:"border-box",
              }}
              onClick={e=>{e.target.select();}}
            />
            <button style={{
              width:"100%",marginTop:6,background:"linear-gradient(135deg,#7a5000,#b07800)",
              border:"none",borderRadius:10,color:"#fff",fontFamily:"var(--f)",
              fontSize:".78rem",fontWeight:800,padding:"8px",cursor:"pointer",
            }} onClick={()=>{
              textareaRef.current?.select();
              document.execCommand('selectAll');
              textareaRef.current?.select();
              try{document.execCommand('copy');showToast("✅ コピーしました！");}catch{}
            }}>
              📋 全選択してコピー
            </button>
          </div>
        )}

        {/* 方法②：ダウンロード */}
        <div style={{
          background:"rgba(255,255,255,.03)",border:"1px solid #1e1e4a",
          borderRadius:14,padding:"12px 14px",
        }}>
          <div style={{fontSize:".72rem",fontWeight:800,color:"#8888cc",marginBottom:6}}>
            💾 方法② ファイルとして保存（Safari/PC）
          </div>
          <div style={{fontSize:".68rem",color:"#3a3a7a",lineHeight:1.8,marginBottom:10}}>
            JSONファイルをダウンロード。Safariなら「ファイル」アプリに保存されます。
          </div>
          <div style={{display:"flex",gap:8}}>
            <button className="bk-export-btn" style={{flex:1,margin:0}}
              onClick={()=>doDownload(false)}>
              <div className="bk-export-icon" style={{width:32,height:32,fontSize:"1rem"}}>💾</div>
              <div style={{flex:1}}>
                <div style={{fontWeight:800,fontSize:".82rem"}}>進捗データを保存</div>
                <div style={{fontSize:".6rem",color:"rgba(255,255,255,.4)"}}>スタンプ・バッジ・設定</div>
              </div>
            </button>
            <button className="bk-export-btn" style={{flex:1,margin:0,
              background:"linear-gradient(135deg,rgba(191,90,242,.2),rgba(255,45,85,.12))",
              borderColor:"rgba(191,90,242,.4)"}}
              onClick={()=>doDownload(true)}>
              <div className="bk-export-icon" style={{background:"linear-gradient(135deg,#bf5af2,#ff2d55)",width:32,height:32,fontSize:"1rem"}}>📦</div>
              <div style={{flex:1}}>
                <div style={{fontWeight:800,fontSize:".82rem"}}>フル保存</div>
                <div style={{fontSize:".6rem",color:"rgba(255,255,255,.4)"}}>おもいで含む</div>
              </div>
            </button>
          </div>
        </div>
      </div>

      {/* ===== インポート ===== */}
      <div className="as">
        <div className="ast">📂 データを復元（インポート）</div>

        {/* 方法A：テキスト貼り付け */}
        <div style={{marginBottom:14}}>
          <div style={{fontSize:".72rem",fontWeight:800,color:"#30d158",marginBottom:6}}>
            📋 方法A：コピーしたテキストを貼り付け
          </div>
          <textarea
            value={restoreText}
            onChange={handlePaste}
            placeholder='メモアプリからコピーしたバックアップデータをここに貼り付け...'
            style={{
              width:"100%",minHeight:80,background:"#06061a",
              border:"1px solid #1a1a40",borderRadius:10,
              padding:"8px 12px",color:"#d8d8f8",fontSize:".72rem",
              fontFamily:"monospace",resize:"vertical",
              boxSizing:"border-box",outline:"none",
            }}
          />
        </div>

        {/* 方法B：ファイル選択 */}
        <div style={{marginBottom:14}}>
          <div style={{fontSize:".72rem",fontWeight:800,color:"#8888cc",marginBottom:6}}>
            📁 方法B：JSONファイルを選択
          </div>
          <input ref={fileRef} type="file" accept=".json,application/json" style={{display:"none"}}
            onChange={handleFile}/>
          <button className="bk-import-file-btn" onClick={()=>fileRef.current?.click()}>
            📁 JSONファイルをえらぶ
          </button>
        </div>

        {restoreErr&&(
          <div style={{background:"rgba(255,45,85,.1)",border:"1px solid rgba(255,45,85,.3)",
            borderRadius:10,padding:"10px 14px",marginBottom:10,
            fontSize:".78rem",color:"#ff6b88",fontWeight:700}}>{restoreErr}</div>
        )}
        {restoreOk&&(
          <div style={{background:"rgba(48,209,88,.1)",border:"1px solid rgba(48,209,88,.3)",
            borderRadius:10,padding:"10px 14px",marginBottom:10,
            fontSize:".78rem",color:"#30d158",fontWeight:700}}>
            ✅ データの復元が完了しました！
          </div>
        )}

        {/* 確認ダイアログ */}
        {confirmRestore&&(
          <div style={{
            background:"linear-gradient(135deg,#1a0010,#2a0020)",
            border:"2px solid #ff2d5566",borderRadius:16,
            padding:"16px",marginBottom:10,
          }}>
            <div style={{fontSize:".8rem",fontWeight:800,color:"#ff6b88",marginBottom:12}}>
              ⚠️ 現在のデータを上書きします。よろしいですか？
            </div>
            <div style={{display:"flex",gap:8}}>
              <button onClick={doRestoreConfirmed} style={{
                flex:1,background:"linear-gradient(135deg,#0a4a1a,#0d6a22)",
                border:"none",borderRadius:12,color:"#fff",
                fontFamily:"var(--f)",fontSize:".82rem",fontWeight:800,
                padding:"10px",cursor:"pointer",
              }}>✅ 復元する</button>
              <button onClick={()=>setConfirmRestore(false)} style={{
                flex:1,background:"rgba(255,255,255,.06)",
                border:"1px solid #2a2a5a",borderRadius:12,color:"#aaa",
                fontFamily:"var(--f)",fontSize:".82rem",fontWeight:800,
                padding:"10px",cursor:"pointer",
              }}>キャンセル</button>
            </div>
          </div>
        )}

        {restoreText.trim()&&!confirmRestore&&(
          <button className="ab" style={{
            width:"100%",marginTop:10,
            background:"linear-gradient(135deg,#0a4a1a,#0d6a22)",
            cursor:"pointer",
          }} onClick={doRestore}>✅ このデータで復元する</button>
        )}
        {restoreText&&(
          <button style={{width:"100%",marginTop:8,background:"none",
            border:"1px solid #2a2a5a",borderRadius:12,color:"#3a3a7a",
            fontFamily:"var(--f)",fontSize:".78rem",fontWeight:800,padding:"8px",cursor:"pointer"}}
            onClick={()=>{setRestoreText("");setRestoreErr("");setRestoreOk(false);setConfirmRestore(false);}}>クリア</button>
        )}
      </div>

      {/* 使い方ガイド */}
      <div className="bk-guide">
        <div style={{fontSize:".72rem",fontWeight:800,color:"#ffd60a",marginBottom:10,letterSpacing:1}}>
          💡 iPhoneでの保存手順（推奨）
        </div>
        {[
          {step:"①",text:"「進捗データをコピー」ボタンを押す"},
          {step:"②",text:"iPhoneの「メモ」アプリを開き、新しいメモに長押し→「ペースト」で貼り付け"},
          {step:"③",text:"復元時はそのメモのテキストをコピーして「復元」の入力欄に貼り付け"},
        ].map((g,i)=>(
          <div key={i} style={{display:"flex",gap:10,marginBottom:8,alignItems:"flex-start"}}>
            <div style={{width:22,height:22,borderRadius:"50%",flexShrink:0,
              background:"linear-gradient(135deg,#003087,#0050c8)",
              display:"flex",alignItems:"center",justifyContent:"center",
              fontSize:".6rem",fontWeight:900,color:"#fff"}}>{g.step}</div>
            <div style={{fontSize:".74rem",color:"#4a4a8a",lineHeight:1.6,paddingTop:2}}>{g.text}</div>
          </div>
        ))}
      </div>
    </div>
  );
}
// ============================================================
//  管理画面（バックアップタブ追加）
// ============================================================
function AdminView({cats,setCats,skills,setSkills,cfg,setCfg,stamps,setStamps,setEarnedBadges,setMemories,playerName,setPlayerName,streak,setStreak,earnedBadges,memories,bannerUrl,setBannerUrl,badgeMode,setBadgeMode,onBack,showToast}){
  const [tab,setTab]=useState("config");
  const [ec,setEc]=useState(cats[0]?.id||"");
  const [editName,setEditName]=useState(playerName);
  const bannerRef=useRef(null);

  const uc=(k,v)=>setCfg(p=>({...p,[k]:v}));
  const addCat=()=>{const id=`cat_${Date.now()}`;setCats(p=>[...p,{id,icon:"⭐",label:"新カテゴリ",color:"#00d4ff",xp:30}]);setSkills(p=>({...p,[id]:[]}));setEc(id);};
  const delCat=(id)=>{if(cats.length<=1){showToast("カテゴリは1つ以上必要","warn");return;}setCats(p=>p.filter(c=>c.id!==id));setSkills(p=>{const n={...p};delete n[id];return n;});setEc(cats.find(c=>c.id!==id)?.id||"");};
  const ucat=(id,k,v)=>setCats(p=>p.map(c=>c.id===id?{...c,[k]:v}:c));
  const addSk=(cid)=>setSkills(p=>({...p,[cid]:[...(p[cid]||[]),{id:`sk_${Date.now()}`,catId:cid,star:1,title:"あたらしいかだい",desc:"せつめい",detail:"くわしいせつめい"}]}));
  const usk=(cid,sid,k,v)=>setSkills(p=>({...p,[cid]:p[cid].map(s=>s.id===sid?{...s,[k]:v}:s)}));
  const delSk=(cid,sid)=>{setSkills(p=>({...p,[cid]:p[cid].filter(s=>s.id!==sid)}));setStamps(p=>{const n={...p};delete n[sid];return n;});};
  const resetStamps=()=>{setStamps({});setEarnedBadges([]);showToast("リセット完了","warn");};
  const resetAll=()=>{setCats(DEFAULT_CATEGORIES);setSkills(DEFAULT_SKILLS);setCfg(DEFAULT_CONFIG);setStamps({});setEarnedBadges([]);setMemories([]);setPlayerName("");showToast("全リセット","warn");};

  const editCat=cats.find(c=>c.id===ec);
  const editSks=skills[ec]||[];

  return(
    <div>
      <button className="bkb" onClick={onBack}>‹ アプリにもどる</button>
      <div style={{fontWeight:900,color:"#ffd60a",marginBottom:14,fontSize:"1rem",letterSpacing:1}}>⚙️ かんりしゃメニュー</div>
      <div className="atabs" style={{flexWrap:"wrap",gap:6}}>
        {[
          {id:"config",l:"⚙️ 設定"},
          {id:"content",l:"📝 内容"},
          {id:"backup",l:"💾 バックアップ"},
          {id:"reset",l:"🗑️ リセット"},
        ].map(t=>(
          <button key={t.id} className={`at ${tab===t.id?"ata":""}`} onClick={()=>setTab(t.id)}>{t.l}</button>
        ))}
      </div>

      {tab==="config"&&(
        <div>
          <div className="as">
            <div className="ast">👤 プレイヤー名</div>
            <div style={{display:"flex",gap:8}}>
              <input className="ai" value={editName} onChange={e=>setEditName(e.target.value)} placeholder="なまえ" style={{flex:1}}/>
              <button className="ab sm" onClick={()=>{setPlayerName(editName);showToast("✅ 名前を変更しました！");}}>変更</button>
            </div>
          </div>
          <div className="as">
            <div className="ast">📱 アプリ表示</div>
            <label className="al">タイトル</label><input className="ai" value={cfg.appTitle} onChange={e=>uc("appTitle",e.target.value)}/>
            <label className="al">サブタイトル</label><input className="ai" value={cfg.appSubtitle} onChange={e=>uc("appSubtitle",e.target.value)}/>
          </div>
          <div className="as">
            <div className="ast">⏱️ 長押し時間（びょう）</div>
            <div style={{display:"flex",gap:10}}>
              <div style={{flex:1}}><label className="al">✅ スタンプ</label><input className="ai" type="number" min=".5" max="10" step=".5" value={cfg.stampMs/1000} onChange={e=>uc("stampMs",parseFloat(e.target.value)*1000)}/></div>
              <div style={{flex:1}}><label className="al">↩️ とりけし</label><input className="ai" type="number" min="1" max="15" step=".5" value={cfg.unstampMs/1000} onChange={e=>uc("unstampMs",parseFloat(e.target.value)*1000)}/></div>
            </div>
          </div>
          <div className="as">
            <div className="ast">🔑 PIN変更</div>
            <input className="ai" type="password" inputMode="numeric" maxLength={6} value={cfg.adminPin} onChange={e=>uc("adminPin",e.target.value)} placeholder="新しいPIN"/>
            <div style={{fontSize:".68rem",color:"#3a3a7a",marginTop:4}}>現在：{cfg.adminPin}</div>
          </div>
          <button className="ab" style={{width:"100%",background:"linear-gradient(135deg,#0a4a1a,#0d6a22)"}} onClick={()=>showToast("✅ 保存しました！")}>💾 ほぞん</button>
          <div className="as" style={{marginTop:12}}>
            <div className="ast">🖼️ ホームバナー画像</div>
            <div style={{fontSize:".74rem",color:"#3a3a7a",lineHeight:1.7,marginBottom:10}}>
              ホーム画面の上部に表示するバナー画像を設定します。
            </div>
            <input ref={bannerRef} type="file" accept="image/*" style={{display:"none"}}
              onChange={e=>{
                const f=e.target.files?.[0]; if(!f)return;
                const r=new FileReader();
                r.onload=ev=>{setBannerUrl(ev.target.result);showToast("✅ バナーを設定しました！");};
                r.readAsDataURL(f);
                e.target.value="";
              }}/>
            {bannerUrl&&(
              <div style={{marginBottom:10,borderRadius:12,overflow:"hidden",border:"1px solid #2a2a5a"}}>
                <img src={bannerUrl} alt="banner preview" style={{width:"100%",maxHeight:100,objectFit:"cover",display:"block"}}/>
              </div>
            )}
            <div style={{display:"flex",gap:8}}>
              <button className="bk-import-file-btn" style={{flex:1,fontSize:".78rem",padding:"10px"}}
                onClick={()=>bannerRef.current?.click()}>
                📁 {bannerUrl?"バナーを変更":"バナーをえらぶ"}
              </button>
              {bannerUrl&&(
                <button className="ab" style={{background:"linear-gradient(135deg,#8a0020,#c0002a)",padding:"10px 14px",fontSize:".72rem"}}
                  onClick={()=>{setBannerUrl("");showToast("バナーを削除しました","warn");}}>
                  削除
                </button>
              )}
            </div>
          </div>
          <div className="as" style={{marginTop:12}}>
            <div className="ast">🎖️ バッジ表示スタイル</div>
            <div style={{display:"flex",gap:8}}>
              {[{id:"logo",label:"🏆 ロゴスタイル"},{id:"flag",label:"🌍 国旗スタイル"}].map(m=>(
                <button key={m.id}
                  onClick={()=>{setBadgeMode(m.id);showToast(`✅ ${m.label}に変更しました！`);}}
                  style={{
                    flex:1,
                    background:badgeMode===m.id?"linear-gradient(135deg,#003087,#0050c8)":"rgba(255,255,255,.05)",
                    border:badgeMode===m.id?"1px solid #0080ff88":"1px solid #1a1a4a",
                    borderRadius:12,padding:"10px 6px",
                    color:badgeMode===m.id?"#fff":"#3a3a7a",
                    fontFamily:"var(--f)",fontSize:".76rem",fontWeight:800,
                    cursor:"pointer",transition:"all .2s",
                  }}>{m.label}</button>
              ))}
            </div>
          </div>
        </div>
      )}

      {tab==="content"&&(
        <div>
          <div className="as">
            <div className="ast" style={{display:"flex",justifyContent:"space-between"}}><span>📂 カテゴリ</span><button className="ab sm" onClick={addCat}>＋</button></div>
            <div style={{display:"flex",gap:6,flexWrap:"wrap",marginBottom:10}}>
              {cats.map(c=><button key={c.id} className={`at ${ec===c.id?"ata":""}`} onClick={()=>setEc(c.id)} style={{fontSize:".72rem"}}>{c.icon} {c.label}</button>)}
            </div>
            {editCat&&(
              <div style={{background:"#07071a",borderRadius:12,padding:12,border:"1px solid #1a1a4a"}}>
                <div style={{display:"flex",gap:8,marginBottom:8}}>
                  <div style={{width:58}}><label className="al">アイコン</label><input className="ai" value={editCat.icon} style={{textAlign:"center",fontSize:"1.2rem"}} onChange={e=>ucat(ec,"icon",e.target.value)}/></div>
                  <div style={{flex:1}}><label className="al">名前</label><input className="ai" value={editCat.label} onChange={e=>ucat(ec,"label",e.target.value)}/></div>
                  <div style={{width:52}}><label className="al">XP</label><input className="ai" type="number" min="10" max="100" step="5" value={editCat.xp||30} onChange={e=>ucat(ec,"xp",parseInt(e.target.value))}/></div>
                  <div style={{width:44}}><label className="al">色</label><input type="color" value={editCat.color||"#00d4ff"} onChange={e=>ucat(ec,"color",e.target.value)} style={{width:"100%",height:38,border:"none",background:"none",cursor:"pointer"}}/></div>
                </div>
                <button className="ab sm" style={{background:"linear-gradient(135deg,#8a0020,#c0002a)"}} onClick={()=>delCat(ec)}>🗑️ このカテゴリを削除</button>
              </div>
            )}
          </div>
          <div className="as">
            <div className="ast" style={{display:"flex",justifyContent:"space-between"}}><span>📝 かだい</span><button className="ab sm" onClick={()=>addSk(ec)}>＋</button></div>
            {editSks.map((sk,i)=>(
              <div key={sk.id} style={{background:"#07071a",borderRadius:12,padding:12,marginBottom:10,border:"1px solid #1a1a4a"}}>
                <div style={{display:"flex",justifyContent:"space-between",marginBottom:8}}>
                  <span style={{color:"#3a3a7a",fontSize:".72rem"}}>#{i+1}</span>
                  <div style={{display:"flex",gap:6,alignItems:"center"}}>
                    <Stars count={sk.star} editable onChange={v=>usk(ec,sk.id,"star",v)}/>
                    <button className="ab sm" style={{background:"linear-gradient(135deg,#8a0020,#c0002a)",padding:"4px 8px"}} onClick={()=>delSk(ec,sk.id)}>✕</button>
                  </div>
                </div>
                <label className="al">タイトル</label><input className="ai" value={sk.title} onChange={e=>usk(ec,sk.id,"title",e.target.value)} style={{marginBottom:8}}/>
                <label className="al">一覧説明</label><textarea className="ai" value={sk.desc} onChange={e=>usk(ec,sk.id,"desc",e.target.value)} style={{minHeight:50,resize:"vertical",marginBottom:8}}/>
                <label className="al">詳細説明</label><textarea className="ai" value={sk.detail} onChange={e=>usk(ec,sk.id,"detail",e.target.value)} style={{minHeight:50,resize:"vertical"}}/>
                <label className="al" style={{marginTop:6}}>
                  📺 お手本どうが URL
                  <span style={{fontSize:".6rem",color:"#3a3a7a",marginLeft:6,fontWeight:400}}>(YouTubeのURLをはりつけ)</span>
                </label>
                <div style={{display:"flex",gap:6,alignItems:"center"}}>
                  <input className="ai" value={sk.videoUrl||""} onChange={e=>usk(ec,sk.id,"videoUrl",e.target.value)}
                    placeholder="https://www.youtube.com/watch?v=..."
                    style={{marginBottom:0,flex:1,fontSize:".76rem"}}/>
                  {sk.videoUrl&&(
                    <button style={{background:"none",border:"1px solid #ff2d5544",borderRadius:8,
                      color:"#ff6b35",padding:"6px 10px",cursor:"pointer",fontFamily:"var(--f)",
                      fontSize:".7rem",fontWeight:800,flexShrink:0,whiteSpace:"nowrap"}}
                      onClick={()=>window.open(sk.videoUrl,"_blank")}>確認</button>
                  )}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {tab==="backup"&&(
        <BackupView
          cats={cats} skills={skills} cfg={cfg} stamps={stamps}
          streak={streak} earnedBadges={earnedBadges} playerName={playerName} memories={memories}
          setCats={setCats} setSkills={setSkills} setCfg={setCfg} setStamps={setStamps}
          setStreak={setStreak} setEarnedBadges={setEarnedBadges}
          setPlayerName={setPlayerName} setMemories={setMemories}
          showToast={showToast}
        />
      )}

      {tab==="reset"&&(
        <div>
          <div className="as">
            <div className="ast">🗑️ スタンプのみリセット</div>
            <div style={{fontSize:".8rem",color:"#3a3a7a",lineHeight:1.7,marginBottom:12}}>スタンプ・バッジを消します。<br/>コンテンツはのこります。</div>
            <button className="ab" style={{width:"100%",background:"linear-gradient(135deg,#8a0020,#c0002a)"}} onClick={resetStamps}>スタンプをぜんぶ消す</button>
          </div>
          <div className="as">
            <div className="ast" style={{color:"#ff2d55"}}>⚠️ 全データリセット</div>
            <div style={{fontSize:".8rem",color:"#ff2d5555",lineHeight:1.7,marginBottom:12}}>全データを初期状態にもどします。<br/>名前も消えます。</div>
            <button className="ab" style={{width:"100%",background:"linear-gradient(135deg,#5a0010,#8a0020)",opacity:.85}} onClick={resetAll}>⚠️ ぜんぶ もとにもどす</button>
          </div>
        </div>
      )}
    </div>
  );
}

// ============================================================
//  グローバルCSS
// ============================================================
const CSS=`
@import url('https://fonts.googleapis.com/css2?family=Nunito:wght@700;800;900&family=Black+Han+Sans&display=swap');
*,*::before,*::after{box-sizing:border-box;margin:0;padding:0;}
:root{
  --bg:#06061a;--sf:#0c0c26;--card:#101028;--bdr:#181840;
  --f:'Nunito',sans-serif;--fd:'Black Han Sans',cursive;
}
body{background:var(--bg);font-family:var(--f);color:#d8d8f8;-webkit-tap-highlight-color:transparent;}
.app{max-width:430px;margin:0 auto;min-height:100svh;display:flex;flex-direction:column;position:relative;overflow:hidden;}

.bg-field{position:fixed;inset:0;z-index:0;pointer-events:none;
  background:
    repeating-linear-gradient(0deg,transparent,transparent 54px,rgba(0,40,120,.07) 54px,rgba(0,40,120,.07) 55px),
    repeating-linear-gradient(90deg,transparent,transparent 54px,rgba(0,40,120,.07) 54px,rgba(0,40,120,.07) 55px),
    radial-gradient(ellipse at 50% 0%,#0a0a2e 0%,#06061a 70%);}
.bg-g1,.bg-g2,.bg-g3{position:fixed;border-radius:50%;filter:blur(90px);pointer-events:none;z-index:0;}
.bg-g1{width:380px;height:380px;top:-120px;left:-100px;background:radial-gradient(circle,rgba(0,48,135,.4),transparent 65%);opacity:.5;}
.bg-g2{width:300px;height:300px;bottom:50px;right:-100px;background:radial-gradient(circle,rgba(26,0,60,.5),transparent 65%);opacity:.4;}
.bg-g3{width:220px;height:220px;top:45%;left:30%;background:radial-gradient(circle,rgba(0,30,80,.3),transparent 65%);opacity:.35;}

.hdr{position:relative;z-index:10;display:flex;align-items:center;gap:10px;padding:0 14px;height:68px;cursor:pointer;user-select:none;overflow:hidden;background:linear-gradient(135deg,#001878 0%,#002fa0 40%,#001060 100%);border-bottom:3px solid transparent;border-image:linear-gradient(90deg,#ff2d55,#ff6b35,#ffd60a,#30d158,#00d4ff,#bf5af2,#ff2d55) 1;}
.hdr-stripe{position:absolute;inset:0;pointer-events:none;background:repeating-linear-gradient(-55deg,transparent 0px,transparent 18px,rgba(255,255,255,.03) 18px,rgba(255,255,255,.03) 36px);}
.hdr-stripe::after{content:'';position:absolute;inset:0;background:linear-gradient(90deg,rgba(0,20,100,.6) 0%,transparent 50%,rgba(0,20,100,.4) 100%);}
.hdr-emblem{display:flex;align-items:center;gap:10px;flex:1;position:relative;z-index:1;}
.hdr-crest{width:46px;height:46px;border-radius:50%;flex-shrink:0;background:linear-gradient(145deg,#002fa0,#0050d0);border:2px solid rgba(255,255,255,.2);display:flex;align-items:center;justify-content:center;box-shadow:0 0 16px rgba(0,80,200,.6),inset 0 1px 0 rgba(255,255,255,.15);position:relative;overflow:hidden;}
.hdr-crest::before{content:'';position:absolute;inset:0;background:radial-gradient(circle at 35% 30%,rgba(255,255,255,.15),transparent 60%);}
.hdr-crest-ball{font-size:1.5rem;filter:drop-shadow(0 0 6px rgba(255,255,255,.4));position:relative;z-index:1;}
.hdr-logo{font-family:var(--fd);font-size:1.4rem;letter-spacing:3px;line-height:1;background:linear-gradient(90deg,#fff 0%,#c8d8ff 100%);-webkit-background-clip:text;-webkit-text-fill-color:transparent;filter:drop-shadow(0 0 8px rgba(100,150,255,.5));}
.hdr-logo span{background:linear-gradient(90deg,#ffd60a,#ffaa00);-webkit-background-clip:text;-webkit-text-fill-color:transparent;}
.hdr-tagline{font-size:.52rem;color:rgba(180,200,255,.6);letter-spacing:2px;margin-top:3px;font-weight:700;}
.hdr-right{display:flex;flex-direction:column;align-items:flex-end;gap:5px;position:relative;z-index:1;flex-shrink:0;}
.hdr-player-badge{background:linear-gradient(135deg,rgba(255,214,10,.2),rgba(255,140,0,.15));border:1px solid rgba(255,214,10,.4);border-radius:8px;padding:2px 10px;font-size:.7rem;font-weight:900;color:#ffd60a;letter-spacing:.5px;box-shadow:0 0 10px rgba(255,214,10,.2);text-shadow:0 0 8px rgba(255,214,10,.5);}
.hdr-player-name::before{content:"⚡ ";}
.hdr-stats{display:flex;gap:5px;}
.hdr-stat-pill{display:flex;align-items:center;gap:3px;border-radius:99px;padding:2px 9px;font-size:.72rem;font-weight:900;}
.hdr-stat-pill.fire{background:rgba(255,107,53,.15);border:1px solid rgba(255,107,53,.35);color:#ff8855;}
.hdr-stat-pill.medal{background:rgba(255,45,85,.12);border:1px solid rgba(255,45,85,.3);color:#ff7799;}
.hdr-stat-pill b{color:#fff;}
.hdr-stat-pill span{font-size:.6rem;opacity:.6;}

.content{flex:1;overflow-y:auto;padding:14px 14px 82px;position:relative;z-index:1;}

.player-card{background:linear-gradient(135deg,#0e0e2c,#141440);border:1px solid #20205888;border-radius:22px;padding:18px;margin-bottom:16px;box-shadow:0 8px 40px rgba(0,0,0,.45),inset 0 1px 0 rgba(255,255,255,.04);}
.pc-top{display:flex;align-items:center;gap:14px;margin-bottom:14px;}
.pc-avatar{width:64px;height:64px;border-radius:50%;border:2px solid;display:flex;align-items:center;justify-content:center;font-size:2rem;background:rgba(255,255,255,.04);flex-shrink:0;}
.stats-row{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-top:14px;}
.stat-box{background:rgba(255,255,255,.03);border:1px solid #1a1a4a;border-radius:12px;padding:8px 4px;text-align:center;}
.stat-val{font-family:var(--fd);font-size:1.2rem;color:#fff;line-height:1;}
.stat-lbl{font-size:.55rem;color:#3a3a7a;margin-top:3px;letter-spacing:.5px;}

.quest-card{background:linear-gradient(135deg,#0a0a28,#100a30);border:1px solid #2a1a5a;border-radius:18px;padding:14px 16px;margin-bottom:16px;cursor:pointer;position:relative;overflow:hidden;box-shadow:0 0 30px rgba(191,90,242,.1);transition:transform .15s;}
.quest-card:active{transform:scale(.97);}
.quest-card::before{content:'';position:absolute;top:0;left:0;right:0;height:2px;background:linear-gradient(90deg,#bf5af2,#ff2d55);opacity:.7;}
.quest-label{font-size:.63rem;font-weight:800;color:#bf5af2;letter-spacing:2px;margin-bottom:10px;}

.sec-lbl{font-size:.7rem;font-weight:800;color:#ffd60a;letter-spacing:3px;text-transform:uppercase;margin-bottom:10px;text-shadow:0 0 8px #ffd60a44;}

.cat-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:22px;}

/* ===== カテゴリカード 新デザイン ===== */
.cc{
  position:relative;overflow:hidden;cursor:pointer;
  border-radius:22px;
  min-height:160px;
  padding:0;
  display:flex;flex-direction:column;
  background:linear-gradient(145deg,#0d0d22,#080818);
  border:1px solid rgba(255,255,255,.07);
  box-shadow:0 8px 32px rgba(0,0,0,.5);
  transition:transform .18s cubic-bezier(.34,1.2,.64,1),box-shadow .2s,border-color .2s;
}
.cc:active{transform:scale(.94);}
.cc:hover{
  border-color:color-mix(in srgb,var(--c) 45%,transparent);
  box-shadow:0 12px 40px rgba(0,0,0,.6),0 0 30px color-mix(in srgb,var(--c) 18%,transparent);
}
.cc-full{
  border-color:color-mix(in srgb,var(--c) 65%,transparent)!important;
  box-shadow:0 0 0 1px color-mix(in srgb,var(--c) 40%,transparent),0 12px 40px rgba(0,0,0,.5),0 0 40px color-mix(in srgb,var(--c) 22%,transparent)!important;
}

/* 背景グロー①（カラー発光） */
.cc-bg-glow{
  position:absolute;top:-20%;left:-10%;
  width:80%;height:70%;
  border-radius:50%;
  background:radial-gradient(circle,color-mix(in srgb,var(--c) 22%,transparent),transparent 65%);
  pointer-events:none;
  transition:opacity .3s;
}
/* 背景グロー②（右下暗め） */
.cc-bg-glow2{
  position:absolute;bottom:-10%;right:-10%;
  width:60%;height:50%;
  border-radius:50%;
  background:radial-gradient(circle,color-mix(in srgb,var(--c) 8%,transparent),transparent 65%);
  pointer-events:none;
}
/* 左上コーナー光沢 */
.cc-shine{
  position:absolute;top:0;left:0;
  width:55%;height:45%;
  background:linear-gradient(135deg,rgba(255,255,255,.07),transparent 60%);
  border-radius:22px 0 0 0;
  pointer-events:none;
}
/* CLEARバッジ */
.cc-clear-badge{
  position:absolute;top:10px;right:10px;
  display:flex;align-items:center;gap:3px;
  background:linear-gradient(135deg,var(--c),color-mix(in srgb,var(--c) 60%,#fff));
  border-radius:99px;padding:3px 10px;
  font-size:.52rem;font-weight:900;color:#fff;letter-spacing:1px;
  box-shadow:0 0 12px color-mix(in srgb,var(--c) 60%,transparent);
  animation:ccClearPulse 2s ease-in-out infinite;
}
@keyframes ccClearPulse{0%,100%{box-shadow:0 0 10px color-mix(in srgb,var(--c) 50%,transparent)}50%{box-shadow:0 0 20px color-mix(in srgb,var(--c) 80%,transparent)}}

/* アイコンラッパー */
.cc-icon-wrap{
  flex:1;
  display:flex;align-items:center;justify-content:flex-start;
  padding:18px 16px 8px;
}
.cc-icon{
  font-size:3.4rem;
  display:block;
  filter:drop-shadow(0 0 16px var(--c)) drop-shadow(0 4px 12px rgba(0,0,0,.6));
  animation:ccIconFloat 4s ease-in-out infinite;
  line-height:1;
}
@keyframes ccIconFloat{0%,100%{transform:translateY(0) scale(1)}50%{transform:translateY(-5px) scale(1.04)}}

/* カテゴリ名 */
.cc-name{
  padding:0 16px 12px;
  font-size:.92rem;font-weight:900;
  color:#fff;letter-spacing:.5px;
  text-shadow:0 2px 8px rgba(0,0,0,.6);
}

/* プログレスエリア */
.cc-prog-area{
  padding:0 14px 14px;
}
.cc-prog{display:flex;align-items:center;gap:8px;}
.cc-bar{
  flex:1;height:4px;
  background:rgba(255,255,255,.07);
  border-radius:99px;overflow:hidden;
}
.cc-fill{
  height:100%;
  background:linear-gradient(90deg,color-mix(in srgb,var(--c) 70%,#fff),var(--c));
  border-radius:99px;
  transition:width .5s cubic-bezier(.4,0,.2,1);
  box-shadow:0 0 6px var(--c);
}
.cc-frac{font-size:.6rem;color:rgba(255,255,255,.35);font-weight:700;white-space:nowrap;}

.hint-box{background:rgba(255,255,255,.02);border:1px solid #181838;border-radius:14px;padding:12px;font-size:.72rem;line-height:2.1;color:#2a2a5a;}
.hint-box b{color:#8888aa;}

.mcs{display:flex;gap:8px;overflow-x:auto;padding-bottom:8px;margin-bottom:14px;scrollbar-width:none;}
.mcs::-webkit-scrollbar{display:none;}
.mcb{flex-shrink:0;display:flex;flex-direction:column;align-items:center;gap:3px;background:var(--card);border:2px solid var(--bdr);border-radius:14px;padding:8px 12px;cursor:pointer;color:#fff;font-family:var(--f);min-width:74px;transition:all .2s;}
.mca{border-color:var(--c)!important;background:color-mix(in srgb,var(--c) 10%,var(--card))!important;box-shadow:0 0 14px color-mix(in srgb,var(--c) 25%,transparent);}

.skc{background:var(--card);border:1px solid var(--bdr);border-radius:16px;padding:14px;display:flex;align-items:center;gap:12px;cursor:pointer;transition:transform .15s,border-color .2s;animation:si .3s ease both;}
@keyframes si{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:translateY(0)}}
.skc:active{transform:scale(.97);}
.skc:hover{border-color:color-mix(in srgb,var(--c) 40%,transparent);}
.skd{border-color:#30d15844!important;background:linear-gradient(135deg,#0d1e10,#071408)!important;}

.dh{background:linear-gradient(135deg,color-mix(in srgb,var(--c) 12%,#0c0c28),#070718);border:1px solid color-mix(in srgb,var(--c) 35%,transparent);border-radius:22px;padding:26px;text-align:center;margin-bottom:14px;position:relative;overflow:hidden;box-shadow:0 0 40px color-mix(in srgb,var(--c) 12%,transparent);}
.dh-glow{position:absolute;inset:0;background:radial-gradient(circle at 50% 20%,color-mix(in srgb,var(--c) 18%,transparent),transparent 60%);pointer-events:none;}
.dd{background:rgba(255,255,255,.03);border:1px solid var(--bdr);border-radius:14px;padding:14px;font-size:.84rem;line-height:1.9;color:#7878a8;margin-bottom:14px;}
.sz{background:var(--card);border:1px dashed #20205888;border-radius:20px;padding:22px;text-align:center;}

.book-hdr{text-align:center;margin-bottom:20px;padding:18px;background:var(--card);border:1px solid var(--bdr);border-radius:20px;}
.bpb{height:8px;background:rgba(255,255,255,.05);border-radius:99px;overflow:hidden;margin:10px 0 4px;}
.bpbf{height:100%;background:linear-gradient(90deg,#bf5af2,#ff2d55);border-radius:99px;transition:width .6s ease;box-shadow:0 0 8px #bf5af255;}
.bi{background:var(--card);border:1px solid var(--bdr);border-radius:14px;padding:12px 8px;text-align:center;position:relative;overflow:hidden;transition:all .3s;}
.bi-got{border-color:#bf5af244!important;background:linear-gradient(135deg,#1a0a30,#100020)!important;box-shadow:0 0 18px rgba(191,90,242,.15);}
.bi-glow{position:absolute;inset:0;background:radial-gradient(circle at 50% 0%,rgba(191,90,242,.1),transparent 60%);pointer-events:none;opacity:0;}
.bi-got .bi-glow{opacity:1;}

.nav{position:fixed;bottom:0;left:50%;transform:translateX(-50%);width:100%;max-width:430px;background:linear-gradient(180deg,rgba(6,6,26,.8),rgba(6,6,26,.97));border-top:1px solid #141430;display:flex;z-index:100;backdrop-filter:blur(24px);padding-bottom:env(safe-area-inset-bottom,0);}
.nb{flex:1;padding:9px 0 7px;background:none;border:none;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:3px;color:#282858;font-family:var(--f);position:relative;transition:color .15s;}
.na{color:#d8d8f8;}
.ni{font-size:1.35rem;}
.nl{font-size:.57rem;font-weight:800;letter-spacing:.5px;}
.nd{position:absolute;bottom:5px;left:50%;transform:translateX(-50%);width:22px;height:2.5px;background:linear-gradient(90deg,#ffd60a,#ff6b35);border-radius:99px;box-shadow:0 0 6px #ffd60a88;}

.toast{position:fixed;top:68px;left:50%;transform:translateX(-50%);background:linear-gradient(135deg,#002080,#0040a0);color:#fff;padding:9px 22px;border-radius:99px;font-size:.82rem;font-weight:800;z-index:500;box-shadow:0 4px 24px rgba(0,32,128,.5);border:1px solid rgba(255,255,255,.08);animation:ti .3s ease;white-space:nowrap;letter-spacing:.5px;}
.tw{background:linear-gradient(135deg,#800020,#b00030)!important;}
@keyframes ti{from{opacity:0;transform:translateX(-50%) translateY(-12px)}to{opacity:1;transform:translateX(-50%) translateY(0)}}

.bkb{display:flex;align-items:center;gap:6px;background:none;border:none;color:#2a2a6a;font-size:.8rem;font-weight:800;cursor:pointer;padding:0;margin-bottom:14px;font-family:var(--f);letter-spacing:1px;}
.bkb:hover{color:#8888aa;}
.ab{background:linear-gradient(135deg,#002070,#0040a0);border:none;border-radius:12px;color:#fff;font-family:var(--f);font-size:.82rem;font-weight:800;padding:10px 18px;cursor:pointer;letter-spacing:.5px;}
.ab.sm{padding:5px 12px;font-size:.72rem;}

.atabs{display:flex;gap:6px;margin-bottom:14px;}
.at{flex:1;background:var(--card);border:1px solid var(--bdr);border-radius:12px;padding:8px 5px;cursor:pointer;color:#3a3a7a;font-family:var(--f);font-size:.74rem;font-weight:800;transition:all .2s;}
.ata{border-color:#ffd60a66!important;color:#ffd60a!important;background:rgba(255,214,10,.06)!important;}
.as{background:var(--card);border:1px solid var(--bdr);border-radius:16px;padding:14px;margin-bottom:12px;}
.ast{font-size:.72rem;font-weight:800;color:#ffd60a;letter-spacing:1px;margin-bottom:12px;}
.al{font-size:.67rem;color:#3a3a7a;margin-bottom:4px;display:block;}
.ai{width:100%;background:#06061a;border:1px solid #1a1a40;border-radius:10px;padding:8px 12px;color:#d8d8f8;font-family:var(--f);font-size:.84rem;outline:none;margin-bottom:8px;}
.ai:focus{border-color:#002080;}

/* ===== 動画パネル ===== */
.vp-wrap{margin-bottom:14px;}
.vp-btn{width:100%;display:flex;align-items:center;gap:10px;background:linear-gradient(135deg,rgba(255,45,85,.14),rgba(255,107,53,.08));border:1.5px solid rgba(255,45,85,.4);border-radius:16px;padding:13px 16px;cursor:pointer;font-family:var(--f);color:#fff;position:relative;overflow:hidden;transition:transform .15s,box-shadow .2s;box-shadow:0 4px 20px rgba(255,45,85,.12);}
.vp-btn:active{transform:scale(.97);}
.vp-btn-icon{width:34px;height:34px;border-radius:50%;flex-shrink:0;background:linear-gradient(135deg,#ff2d55,#ff6b35);display:flex;align-items:center;justify-content:center;font-size:.82rem;font-weight:900;box-shadow:0 0 14px rgba(255,45,85,.5);}
.vp-btn-text{flex:1;font-size:.86rem;font-weight:800;text-align:left;letter-spacing:.5px;}
.vp-btn-yt{font-size:.6rem;font-weight:900;letter-spacing:1px;background:linear-gradient(135deg,#cc0000,#ff2d55);border-radius:6px;padding:3px 8px;color:#fff;flex-shrink:0;box-shadow:0 2px 8px rgba(200,0,0,.3);}

/* ===== おもいでゾーン ===== */
.mem-zone{margin-top:14px;background:linear-gradient(135deg,color-mix(in srgb,var(--c) 8%,#0a0a28),#080820);border:1.5px solid color-mix(in srgb,var(--c) 30%,transparent);border-radius:18px;padding:16px;}
.mem-zone-title{display:flex;justify-content:space-between;align-items:center;font-size:.78rem;font-weight:800;color:var(--c);letter-spacing:.5px;margin-bottom:12px;}
.mem-open-btn{width:100%;display:flex;align-items:center;gap:10px;background:rgba(255,255,255,.04);border:1.5px dashed color-mix(in srgb,var(--c) 40%,transparent);border-radius:14px;padding:14px 16px;cursor:pointer;font-family:var(--f);color:#d8d8f8;transition:all .2s;}
.mem-open-btn:active{transform:scale(.97);}
.mem-form{background:rgba(255,255,255,.02);border:1px solid rgba(255,255,255,.06);border-radius:12px;padding:14px;animation:vpSlide .2s ease;}
@keyframes vpSlide{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:translateY(0)}}
.mem-file-btn{background:linear-gradient(135deg,#1a1a40,#2a2a60);border:1px solid #3a3a7a;border-radius:10px;color:#d8d8f8;font-family:var(--f);font-size:.76rem;font-weight:800;padding:8px 14px;cursor:pointer;white-space:nowrap;flex-shrink:0;}
.mem-file-btn:active{transform:scale(.97);}

/* ===== おもいでカード ===== */
.mem-card{background:linear-gradient(135deg,color-mix(in srgb,var(--c) 6%,#0e0e28),#0a0a20);border:1px solid color-mix(in srgb,var(--c) 25%,transparent);border-radius:18px;padding:16px;position:relative;overflow:hidden;animation:si .3s ease both;}
.mem-card-glow{position:absolute;inset:0;pointer-events:none;background:radial-gradient(circle at 20% 10%,color-mix(in srgb,var(--c) 10%,transparent),transparent 50%);}

/* ===== 💾 バックアップ UI ===== */
.bk-summary{
  background:linear-gradient(135deg,#0a0a28,#0e0e38);
  border:1px solid #1e1e50;border-radius:18px;padding:16px;margin-bottom:12px;
}
.bk-summary-title{
  font-size:.7rem;font-weight:800;color:#ffd60a;letter-spacing:2px;margin-bottom:12px;
}
.bk-summary-grid{
  display:grid;grid-template-columns:1fr 1fr;gap:8px;
}
.bk-stat{
  display:flex;align-items:center;gap:10px;
  background:rgba(255,255,255,.03);border:1px solid #1a1a40;
  border-radius:12px;padding:10px 12px;
}
.bk-export-btn{
  width:100%;display:flex;align-items:center;gap:12px;
  background:linear-gradient(135deg,rgba(0,80,200,.25),rgba(0,48,135,.15));
  border:1.5px solid rgba(0,100,255,.4);
  border-radius:16px;padding:14px 16px;cursor:pointer;
  font-family:var(--f);color:#fff;
  transition:all .18s;
  box-shadow:0 4px 20px rgba(0,80,200,.15);
}
.bk-export-btn:hover{box-shadow:0 4px 28px rgba(0,80,200,.3);transform:translateY(-1px);}
.bk-export-btn:active{transform:scale(.97);}
.bk-export-icon{
  width:40px;height:40px;border-radius:12px;flex-shrink:0;
  background:linear-gradient(135deg,#003087,#0050c8);
  display:flex;align-items:center;justify-content:center;
  font-size:1.2rem;
  box-shadow:0 0 16px rgba(0,80,200,.4);
}
.bk-import-file-btn{
  width:100%;display:flex;align-items:center;justify-content:center;gap:8px;
  background:linear-gradient(135deg,rgba(255,214,10,.12),rgba(255,107,53,.08));
  border:1.5px solid rgba(255,214,10,.35);
  border-radius:14px;padding:13px;cursor:pointer;
  font-family:var(--f);font-size:.86rem;font-weight:800;
  color:#ffd60a;letter-spacing:.5px;
  transition:all .18s;
}
.bk-import-file-btn:active{transform:scale(.97);}
.bk-guide{
  background:rgba(255,255,255,.02);border:1px solid #181838;
  border-radius:16px;padding:16px;margin-top:4px;
}
`;

